EX = dict(id="nism-xv", series="XV", code="NISM Series XV", short="Research Analyst", title="Research Analyst",
 track="nism-adv", tag="XV", level="expert",
 blurb="Economy, industry, company, valuation and technicals, plus the SEBI rules for publishing research. Fifteen chapters, deeply worked.",
 intro="NISM Series XV is required for SEBI-registered research analysts and research entities. It spans the whole analyst's toolkit, from macroeconomics and financial statement analysis to valuation and technical analysis, and finishes with the legal framework that governs what can be published and how.",
 who="Equity and debt analysts, portfolio managers, sell-side and buy-side researchers, finfluencers and educators who publish research, and anyone who wants a rigorous foundation in fundamental and technical analysis.",
 qs=100, mins=120, **{"pass": 60}, pass_=60, neg="25% of marks", marks=100, days=42,
 glance=[["Format", "80 multiple-choice questions plus 5 case-based sets (4 questions each); the mocks here use scenario questions in place of cases"], ["Questions and marks", "100 questions, 1 mark each, 100 marks"], ["Duration", "2 hours"], ["Passing score", "60 marks (60%)"], ["Negative marking", "25% of a question's marks, so 0.25 per wrong answer"], ["Certificate validity", "Three years; renew through NISM"], ["Where it leads", "SEBI registration as a research analyst"]],
 checklist=["Redo every ratio and valuation formula on paper.", "Learn the SEBI RA disclosure and trading-restriction rules exactly.", "Revise indicator definitions: RSI, MACD, Bollinger, moving averages.", "Revise chapters 8, 10, 14 and 15; together they carry about half of the marks.", "Take Mock 5 in one timed sitting with negative marking."],
 tips=["Negative marking applies. Guess only after eliminating two options.", "Write the formula before computing; examiners often include the inverse as a distractor.", "Case-style questions repeat one scenario; read the scenario once carefully, then answer all four.", "For regulation questions, look for the word 'shall' in your memory of the rule.", "Chart-pattern questions describe the shape in words; draw it."],
 sheet=[("Formulas", [["Measure", "Formula"], ["P/E", "Price ÷ EPS"], ["EV", "Market cap + debt − cash"], ["ROE", "Net profit ÷ shareholders' equity"], ["DuPont ROE", "Net margin × Asset turnover × Equity multiplier"], ["Current ratio", "Current assets ÷ current liabilities"], ["Interest coverage", "EBIT ÷ Interest"], ["CAPM", "Rf + β × (Rm − Rf)"], ["Gordon growth", "P = D1 ÷ (r − g)"], ["Free cash flow", "CFO − Capex"], ["Sharpe", "(Rp − Rf) ÷ σp"]]),
        ("Indicator cheat sheet", [["Indicator", "Reading"], ["RSI (14)", "Above 70 overbought, below 30 oversold"], ["MACD", "Signal-line crossover shows momentum change"], ["Bollinger Bands", "20-period average ± 2 standard deviations"], ["Golden cross", "50-day moving average crosses above the 200-day"], ["Death cross", "50-day moving average crosses below the 200-day"], ["Fibonacci retracement", "38.2%, 50%, 61.8%"]])],
 units=[
 dict(n=1, title="Introduction to the research analyst profession", w=1,
  overview="Who a research analyst is and what the role demands.",
  focus=["Role, skills and responsibilities."],
  facts=[("Research analyst","A research analyst studies securities, companies or markets and publishes recommendations, targets or opinions that investors may rely on.","A person who writes a report recommending a share with a target price.","A research analyst executes trades for clients."),
   ("Buy-side and sell-side","Sell-side analysts work for brokers and publish research for clients; buy-side analysts work for fund managers and research for their own investment decisions.","An analyst at a mutual fund researches stocks only for the fund's use.","Buy-side analysts publish reports for the public."),
   ("Objectivity and independence","Research must be independent, based on facts and free of undue influence from the subject company or trading desks.","An analyst resists pressure to change a rating after the company objects.","An analyst may change a rating at the request of the subject company.")]),
 dict(n=2, title="Introduction to the securities market", w=2,
  overview="A rapid overview of the market that analysts operate in.",
  focus=["Primary and secondary markets, participants and regulators."],
  facts=[("Securities market regulators","SEBI regulates the securities market, RBI the money market and banks, and exchanges oversee their members.","A research report on listed shares is subject to the capital-market regulator.","The RBI regulates research analysts."),
   ("Market segments","The securities market has equity, debt, derivatives and commodity segments, each with its own instruments and participants.","An analyst may cover shares, bonds and futures contracts.","Securities markets have only an equity segment."),
   ("Listing and disclosure","Listed companies must make continuous disclosures under the SEBI listing regulations, which are the primary source of information for analysts.","A company files its quarterly results and announces material events on the exchange.","Listed companies need not disclose results to the public.")]),
 dict(n=3, title="Terminology in equity and debt markets", w=2,
  overview="Key terms the analyst must use correctly.",
  focus=["Equity and debt terms."],
  facts=[("Market capitalisation","Market capitalisation is share price multiplied by shares outstanding, and classifies companies as large, mid or small cap.","A company with 50 crore shares at ₹200 has a value of ₹10,000 crore.","Market capitalisation is the company's total assets."),
   ("Yield to maturity","Yield to maturity is the annualised return on a bond if held to maturity and coupons are reinvested at the same rate.","A bond priced below face value has a yield above its coupon.","Yield to maturity equals the coupon rate always."),
   ("Face value and issue price","Face value is the nominal value of a security, while the issue price is what investors pay at the time of issue, which may differ.","A share with face value ₹10 is issued at ₹250.","Issue price is always equal to face value."),
   ("Credit spread","Credit spread is the extra yield on a risky bond over a risk-free government bond of similar maturity, compensating for credit risk.","A corporate bond yields 2% more than a similar G-sec.","Credit spread is the difference between bid and ask.")]),
 dict(n=4, title="Fundamentals of research", w=5,
  overview="The framework for doing research: approaches, sources and a disciplined process.",
  focus=["Top-down and bottom-up.", "Qualitative and quantitative analysis.", "Research process and data sources."],
  visuals=[("flow", "Top-down approach", ["Economy", "Industry", "Company", "Valuation", "Recommendation"])],
  facts=[("Top-down approach","The top-down approach starts with the economy, then selects industries and finally companies.","An analyst first judges growth, then picks sectors, then picks stocks.","A top-down approach starts with a single stock."),
   ("Bottom-up approach","The bottom-up approach starts with individual company analysis and gives less weight to macro and sector views.","An analyst picks strong businesses irrespective of sector or economy.","A bottom-up approach starts with the global economy."),
   ("Fundamental analysis","Fundamental analysis estimates a security's intrinsic value from economic, industry and company factors and compares it with market price.","An analyst studies earnings and cash flow to judge fair value.","Fundamental analysis relies only on price charts."),
   ("Technical analysis","Technical analysis studies price and volume history to forecast future price moves, assuming patterns repeat.","An analyst studies charts and indicators rather than financial statements.","Technical analysis studies a company's balance sheet."),
   ("Qualitative analysis","Qualitative analysis assesses non-numerical factors such as management quality, brand, competitive position and governance.","An analyst evaluates the integrity and track record of the management.","Qualitative analysis uses only financial ratios."),
   ("Quantitative analysis","Quantitative analysis uses numerical data and models, such as ratios, forecasts and statistics, to evaluate securities.","An analyst builds a forecast model of revenue and profits.","Quantitative analysis ignores numbers."),
   ("Intrinsic value","Intrinsic value is the estimated true worth of a security based on fundamentals, which may differ from market price.","A stock priced at ₹80 is estimated to be worth ₹110.","Intrinsic value is today's market price."),
   ("Primary and secondary data","Primary data is collected directly by the analyst, such as management interviews and channel checks; secondary data is taken from existing sources like filings.","An analyst visits a plant to gather information first-hand.","Annual reports are primary data collected by the analyst."),
   ("Research process","The research process involves defining the objective, collecting data, analysing, valuing, forming a view, writing and monitoring.","An analyst follows steps from data gathering to publishing and updating.","The research process ends with the first report."),
   ("Margin of safety","Margin of safety is the gap between intrinsic value and the price paid, providing a cushion against errors in estimation.","An analyst buys only when price is well below estimated value.","A margin of safety means paying more than intrinsic value.")]),
 dict(n=5, title="Economic analysis", w=5,
  overview="How the economy drives sectors and stocks: growth, inflation, policy and the cycle.",
  focus=["GDP, inflation, fiscal and monetary policy.", "Business cycle and indicators."],
  visuals=[("table", "Monetary policy tools", [["Tool", "Effect"], ["Repo rate", "Rate at which banks borrow from RBI"], ["CRR", "Share of deposits banks keep with RBI"], ["SLR", "Share of deposits banks hold in liquid assets"], ["OMO", "Buying or selling G-secs to adjust liquidity"]], [130, 340])],
  facts=[("GDP","Gross Domestic Product is the total value of goods and services produced within a country in a period, a measure of economic activity.","A country's total output for the year rises 6.5%.","GDP is the total government spending."),
   ("Inflation","Inflation is the sustained rise in the general price level, measured in India by the Consumer Price Index and the Wholesale Price Index.","The general price level rises 5% compared with last year.","Inflation is a fall in the general price level."),
   ("CPI and WPI","CPI measures changes in retail prices faced by consumers, while WPI measures wholesale prices of goods. The RBI targets CPI inflation.","The policy target is based on retail prices.","The RBI targets WPI inflation."),
   ("Fiscal deficit","The fiscal deficit is government expenditure minus revenue (excluding borrowings), showing how much the government must borrow.","The government spends ₹50 lakh crore against receipts of ₹45 lakh crore.","The fiscal deficit equals the trade deficit."),
   ("Current account deficit","The current account deficit arises when a country's imports of goods, services and transfers exceed its exports.","India buys more from the world than it sells.","A current account deficit means the government has a budget deficit."),
   ("Monetary policy","Monetary policy is the central bank's use of interest rates and liquidity tools to manage inflation and growth.","The RBI raises the repo rate to control prices.","Monetary policy is set by the finance ministry."),
   ("Fiscal policy","Fiscal policy is the government's use of taxation and spending to influence the economy.","The government cuts taxes to stimulate demand.","Fiscal policy is set by the central bank."),
   ("Business cycle","The business cycle consists of expansion, peak, contraction and trough, with different sectors outperforming in each phase.","An economy moves from recovery to boom and then slowdown.","The economy grows in a straight line without cycles."),
   ("Leading indicators","Leading indicators such as new orders and PMI change before the economy turns and help forecast direction.","A rise in new orders signals growth ahead.","Leading indicators change after the economy turns."),
   ("PMI","The Purchasing Managers' Index surveys business activity; a reading above 50 indicates expansion and below 50 contraction.","A manufacturing PMI of 56 shows expansion.","A PMI below 50 shows expansion."),
   ("IIP","The Index of Industrial Production tracks changes in the volume of production in mining, manufacturing and electricity.","A monthly number shows industrial output rising 4%.","IIP measures retail inflation."),
   ("Exchange rate impact","A weaker rupee helps exporters' revenues but raises import costs, affecting sectors differently.","IT exporters gain when the rupee depreciates.","A weaker rupee hurts all companies equally."),
   ("Interest rate impact","Higher interest rates raise borrowing costs and discount rates, which usually pressure valuations and rate-sensitive sectors.","A rate hike hurts real estate and auto stocks.","Higher interest rates always lift all share prices.")]),
 dict(n=6, title="Industry analysis", w=8,
  overview="Industries have their own economics. This chapter equips analysts to assess structure, competition and lifecycle.",
  focus=["Porter's five forces.", "Industry life cycle.", "Cyclical versus defensive."],
  visuals=[("flow", "Porter's five forces", ["Rivalry", "New entrants", "Substitutes", "Buyer power", "Supplier power"])],
  facts=[("Porter's five forces","Porter's model assesses industry attractiveness by competitive rivalry, threat of new entrants, threat of substitutes, bargaining power of buyers and suppliers.","An analyst evaluates how easy it is for rivals to enter and compete.","Porter's model measures a company's profit margin."),
   ("Barriers to entry","Barriers to entry, such as capital needs, regulation, brands and scale, protect existing firms from new competitors.","A telecom sector needs spectrum and heavy capital.","High barriers to entry make an industry easy to enter."),
   ("Industry life cycle","Industries pass through start-up, growth, maturity and decline stages, with different growth rates and risks.","A new technology sector is in rapid growth with high uncertainty.","All industries remain in the growth stage."),
   ("Cyclical industry","A cyclical industry's earnings rise and fall sharply with the economic cycle, as in steel, autos and capital goods.","A steel company's profits swing with the economy.","Cyclical industries have stable earnings in all conditions."),
   ("Defensive industry","A defensive industry sells essentials with stable demand, such as FMCG, utilities and pharma, and holds up better in downturns.","A toothpaste maker's sales remain steady in a recession.","Defensive industries are the most sensitive to the economic cycle."),
   ("Industry concentration","Concentration measures how much of the market is held by a few firms; the Herfindahl-Hirschman index is one such measure.","Three firms hold 80% of the market, indicating concentration.","A concentrated industry has many equal small players."),
   ("Cost structure","Operating leverage depends on fixed versus variable costs; high fixed costs magnify profit swings as volume changes.","A firm with high fixed costs sees profits jump sharply when sales rise.","Fixed costs change in proportion to sales."),
   ("Substitute threat","Substitutes limit the prices an industry can charge, as customers can switch to alternatives.","Rising bus fares push travellers to trains.","Substitutes have no effect on pricing."),
   ("Regulation and policy","Government policy, taxes and regulation can change industry profitability, such as price controls in pharma or spectrum charges in telecom.","A price cap reduces margins in a regulated industry.","Regulation never affects industry profits."),
   ("PESTLE analysis","PESTLE reviews political, economic, social, technological, legal and environmental factors that affect an industry.","An analyst lists the policy, tech and legal drivers for a sector.","PESTLE is a ratio of price to earnings."),
   ("Market share","Market share is a company's sales as a percentage of the industry total and shows competitive strength over time.","A firm's share rises from 20% to 25% over three years.","Market share is the same as profit margin."),
   ("Capacity utilisation","Capacity utilisation shows the share of installed capacity actually used; low utilisation signals weak demand or excess capacity.","A cement industry running at 60% capacity has spare supply.","High capacity utilisation always signals weak demand."),
   ("SWOT analysis","SWOT lists a company's strengths, weaknesses, opportunities and threats to summarise its position.","An analyst lists internal strengths and external risks in one table.","SWOT is a method of calculating cost of capital.")]),
 dict(n=7, title="Company analysis: business and governance", w=6,
  overview="Before the numbers, understand the business and the people running it.",
  focus=["Business model and moat.", "Management quality.", "Corporate governance red flags."],
  facts=[("Business model","A business model describes how a company creates, delivers and captures value, and what drives its revenue and costs.","An analyst maps how a company earns each rupee of revenue.","A business model is the company's balance sheet."),
   ("Economic moat","An economic moat is a durable competitive advantage, such as brand, network effect, cost advantage or switching cost, protecting long-term profits.","A strong brand allows a company to charge premium prices for years.","An economic moat is a short-lived advantage."),
   ("Management quality","Management quality is judged by track record, capital allocation, transparency, integrity and alignment with shareholders.","An analyst reviews how past acquisitions performed and whether guidance was met.","Management quality is irrelevant if the numbers are good."),
   ("Corporate governance","Corporate governance is the system of rules and practices by which a company is directed and controlled, protecting shareholders' interests.","Independent directors, audit committee and transparent disclosures.","Corporate governance is only about paying dividends."),
   ("Board independence","Independent directors on the board and its committees provide oversight free from management and promoter influence.","A board has independent directors chairing the audit committee.","Independent directors are promoter relatives."),
   ("Related-party transactions","Dealings between a company and its promoters or their entities may favour insiders, so they require disclosure and approval.","A company buys goods from an entity owned by the promoter's family.","Related-party transactions need no disclosure."),
   ("Promoter pledge","Pledging of promoter shares to raise loans is a red flag, because a price fall can lead to forced sale and loss of control.","Promoters have pledged a large share of their stake.","A high promoter pledge is a positive sign."),
   ("Auditor red flags","Frequent changes of auditors, qualified audit opinions and delays in results can signal accounting or governance problems.","An auditor resigns mid-year citing lack of information.","A qualified opinion is a sign of clean accounts."),
   ("Capital allocation","Capital allocation is how management uses cash: reinvesting, acquiring, repaying debt or returning cash to shareholders.","A company uses free cash flow to buy back shares and cut debt.","Capital allocation means issuing more debt."),
   ("ESG","Environmental, social and governance factors affect long-term risk and returns and are increasingly part of research.","An analyst reviews a company's emissions and labour practices.","ESG factors have no financial relevance."),
   ("Disclosure quality","Transparent, timely and consistent disclosure builds trust; poor or selective disclosure is a warning sign.","A company explains its results and risks in detail.","Disclosures are only a legal formality.")]),
 dict(n=8, title="Company analysis: financial analysis", w=12,
  overview="The core of the analyst's craft: reading financial statements and ratios. Expect many calculation questions.",
  focus=["Profitability, liquidity, leverage and efficiency ratios.", "DuPont analysis.", "Cash flow statement.", "Quality of earnings."],
  visuals=[("formula", "DuPont", "ROE = Net profit margin × Asset turnover × Equity multiplier"), ("table", "Ratio families", [["Family", "Examples"], ["Liquidity", "Current ratio, quick ratio"], ["Leverage", "Debt-to-equity, interest coverage"], ["Profitability", "ROE, ROCE, net margin"], ["Efficiency", "Inventory turnover, receivable days"]], [130, 340])],
  facts=[("Income statement","The income statement reports revenue, expenses and profit over a period, showing how sales become net profit.","An analyst studies a company's sales and profit for the year.","The income statement shows assets and liabilities."),
   ("Balance sheet","The balance sheet shows a company's assets, liabilities and shareholders' equity at a point in time; assets equal liabilities plus equity.","A snapshot of what the company owns and owes on 31 March.","The balance sheet shows cash flows for a year."),
   ("Cash flow statement","The cash flow statement reports cash from operating, investing and financing activities, showing how cash moved.","An analyst checks whether profits convert into cash.","The cash flow statement lists only dividends."),
   ("EBITDA","EBITDA is earnings before interest, tax, depreciation and amortisation, a proxy for operating performance before capital structure and non-cash charges.","A firm's operating profit before depreciation and financing cost.","EBITDA is the net profit after tax."),
   ("Net profit margin","Net profit margin is net profit divided by revenue, showing how much of each rupee of sales becomes profit.","Profit of ₹10 crore on revenue of ₹100 crore is a 10% margin.","Net profit margin is profit divided by equity."),
   ("Return on equity","ROE is net profit divided by shareholders' equity, showing the return earned on owners' funds.","A firm earns ₹20 crore on equity of ₹100 crore.","ROE is net profit divided by total assets."),
   ("Return on capital employed","ROCE is EBIT divided by capital employed (equity plus debt), measuring returns on all capital in the business.","EBIT of ₹30 crore on capital employed of ₹150 crore gives 20%.","ROCE uses only shareholders' equity in the denominator."),
   ("Current ratio","The current ratio is current assets divided by current liabilities, showing short-term liquidity.","A firm with current assets of ₹200 crore and current liabilities of ₹100 crore has a ratio of 2.","The current ratio measures long-term debt."),
   ("Quick ratio","The quick ratio excludes inventory from current assets and divides by current liabilities, a stricter test of liquidity.","An analyst removes stock from current assets before testing liquidity.","The quick ratio includes inventory."),
   ("Debt-to-equity ratio","The debt-to-equity ratio is total debt divided by shareholders' equity and shows financial leverage.","A company with ₹300 crore debt and ₹200 crore equity has a ratio of 1.5.","Debt-to-equity is profit divided by equity."),
   ("Interest coverage ratio","Interest coverage is EBIT divided by interest expense, showing how comfortably a company can pay interest.","EBIT of ₹60 crore against interest of ₹20 crore gives 3 times.","Interest coverage is debt divided by equity."),
   ("Asset turnover","Asset turnover is revenue divided by total assets and shows how efficiently assets generate sales.","A firm generates ₹2 of sales for every ₹1 of assets.","Asset turnover measures profit per share."),
   ("Inventory days","Inventory days is average inventory divided by cost of sales times 365, showing how long stock sits before being sold.","A firm holds stock for 60 days on average.","Inventory days measure how long customers take to pay."),
   ("Receivable days","Receivable days measure the average time taken to collect payment from customers.","A firm waits 75 days to collect its dues.","Receivable days measure the time taken to pay suppliers."),
   ("Cash conversion cycle","The cash conversion cycle is inventory days plus receivable days minus payable days, showing how long cash is tied up in operations.","A shorter cycle means cash returns to the business faster.","A longer cash conversion cycle is always better."),
   ("Free cash flow","Free cash flow is cash from operations minus capital expenditure, representing cash available to investors after sustaining the business.","A company generates ₹100 crore from operations and spends ₹40 crore on capex.","Free cash flow equals net profit."),
   ("Operating leverage","Operating leverage reflects the share of fixed costs in total costs; higher fixed costs magnify the effect of sales changes on profit.","A small rise in sales produces a large rise in profit for a firm with big fixed costs.","Operating leverage measures debt in the capital structure."),
   ("Quality of earnings","Earnings are high quality when they are backed by cash flows, repeatable and not inflated by one-offs or aggressive accounting.","A company's profit is consistently supported by operating cash flow.","Earnings quality is judged by the size of one-off gains."),
   ("Common-size statements","Common-size statements express every line as a percentage of a base such as revenue, making comparison across firms and years easier.","An analyst expresses each cost as a share of sales.","Common-size statements show absolute amounts."),
   ("Ind AS","Indian Accounting Standards converge with international standards and govern how listed Indian companies prepare financial statements.","A listed company follows standards aligned with IFRS.","Ind AS applies only to banks."),
   ("Earnings per share","EPS equals profit after tax available to equity shareholders divided by the weighted average number of shares.","Profit of ₹100 crore on 20 crore shares is ₹5 per share.","EPS is the dividend per share."),
   ("Working capital","Working capital is current assets minus current liabilities and shows the funds tied up in day-to-day operations.","A firm's short-term assets exceed its short-term obligations by ₹50 crore.","Working capital is long-term debt.")]),
 dict(n=9, title="Corporate actions", w=5,
  overview="Dividends, bonuses, splits, rights, buybacks, mergers and open offers, and what each means for shareholders and valuation.",
  focus=["Ex-date and record date.", "Bonus, split and rights.", "Mergers, demergers, buybacks, delisting."],
  visuals=[("flow", "Dividend timeline", ["Board declares", "Record date set", "Ex-date", "Payment"])],
  facts=[("Ex-dividend date","The ex-dividend date is the date from which a share trades without the right to the declared dividend; buyers on or after it do not receive it.","An investor buys on the ex-date and does not get the dividend.","Buyers on the ex-date receive the dividend."),
   ("Record date","The record date is the date on which a shareholder must be on the company's register to be eligible for a corporate benefit.","Only holders on a specified date are entitled to the dividend.","The record date is the date the dividend is paid."),
   ("Bonus issue","A bonus issue gives existing shareholders extra shares free of cost in a ratio, capitalising reserves, with the price adjusting.","A company gives 1 free share for every 2 held.","A bonus issue raises fresh funds for the company."),
   ("Stock split","A stock split reduces the face value and increases the number of shares in the same ratio, leaving market capitalisation unchanged.","A ₹10 face value share splits into five shares of ₹2 each.","A stock split reduces the company's equity capital."),
   ("Rights issue","A rights issue offers existing shareholders the right to subscribe to new shares in proportion to their holding, usually at a discount.","A company offers 1 new share for every 5 held at ₹150.","A rights issue is offered to new investors first."),
   ("Share buyback","A buyback is the repurchase of a company's own shares, reducing the share count and returning cash to shareholders, through tender offer or open market.","A company buys back its shares at a premium to market price.","A buyback increases the number of shares."),
   ("Merger","A merger combines two companies into one, with the shareholders of the merged company receiving shares in the surviving company under a swap ratio.","One company absorbs another and issues its shares to the other's holders.","A merger splits a company into two."),
   ("Demerger","A demerger splits a business into two or more entities, and shareholders receive shares in the new entity in a given ratio.","A conglomerate separates its financial arm into a new listed company.","A demerger combines two companies."),
   ("Open offer","An open offer requires an acquirer who crosses the 25% trigger or acquires control to offer to buy shares from public shareholders under SEBI takeover rules.","An acquirer who takes 26% must make an offer to other shareholders.","An open offer is made only to the promoters."),
   ("Delisting","Delisting is the removal of a company's securities from an exchange, either voluntarily or compulsorily.","A company buys out public shareholders and its shares stop trading.","Delisting means a company issues new shares."),
   ("Dividend yield","Dividend yield is the annual dividend per share divided by the share price and shows income return.","A share at ₹200 paying ₹6 yields 3%.","Dividend yield is profit per share."),
   ("Dividend payout ratio","The dividend payout ratio is the share of profit paid as dividends; the rest is retained for growth.","A company pays ₹4 of ₹10 EPS, a 40% payout.","The payout ratio is dividend divided by price.")]),
 dict(n=10, title="Valuation principles", w=12,
  overview="Turning analysis into a price. Intrinsic and relative valuation methods, their assumptions and limits.",
  focus=["DCF and its inputs.", "P/E, P/B, EV/EBITDA.", "Dividend discount model.", "WACC and CAPM."],
  visuals=[("formula", "Gordon growth", "Value today = Next year's dividend ÷ (Required return − Growth rate)"), ("formula", "CAPM", "Required return = Risk-free rate + Beta × (Market return − Risk-free rate)")],
  facts=[("Discounted cash flow","DCF values a business as the present value of its expected future free cash flows, discounted at the required rate of return.","An analyst projects cash flows for ten years and discounts them to today.","DCF values a business by multiplying earnings by a ratio."),
   ("Free cash flow to firm","FCFF is the cash available to all capital providers after operating costs and investment, discounted at WACC to value the firm.","An analyst computes cash available to both lenders and shareholders.","FCFF is cash available only to shareholders."),
   ("Free cash flow to equity","FCFE is the cash available to shareholders after debt payments and reinvestment, discounted at the cost of equity.","An analyst values the equity using cash left after servicing debt.","FCFE is discounted at WACC."),
   ("WACC","The weighted average cost of capital blends the cost of equity and after-tax cost of debt in proportion to their weights, and is the discount rate for FCFF.","A firm funded 60% by equity at 12% and 40% by debt at 8% (after tax 6%) has a blended cost.","WACC uses only the cost of equity."),
   ("Cost of equity (CAPM)","CAPM estimates the cost of equity as the risk-free rate plus beta times the equity risk premium.","With a risk-free rate of 6%, beta of 1.2 and market return of 12%, the required return is 13.2%.","CAPM estimates cost of debt."),
   ("Terminal value","Terminal value represents the value of cash flows beyond the explicit forecast period, often a large share of total DCF value.","An analyst assumes cash flows grow steadily forever after year ten.","Terminal value is ignored in DCF."),
   ("Dividend discount model","The DDM values a share as the present value of expected dividends; in the Gordon model, value = D1 ÷ (r − g).","A share paying ₹5 next year with growth 5% and required return 15% is valued at ₹50.","The DDM values shares using book value."),
   ("Price-to-earnings multiple","P/E divides price by earnings per share and is a relative valuation tool, compared with peers and history.","A stock at 25 times earnings is compared with sector peers.","P/E is price divided by book value."),
   ("Price-to-book multiple","P/B compares market price with book value per share, widely used for banks and asset-heavy firms.","A bank trading at 2.5 times book value.","P/B is used mainly for software firms."),
   ("EV/EBITDA","EV/EBITDA compares enterprise value with operating earnings before depreciation, neutral to capital structure, useful for comparing leveraged firms.","A firm with EV of ₹5,000 crore and EBITDA of ₹500 crore trades at 10 times.","EV/EBITDA ignores debt entirely."),
   ("Enterprise value","Enterprise value is market capitalisation plus debt minus cash, the price of the whole business.","A company with market cap ₹1,000 crore, debt ₹300 crore and cash ₹100 crore has EV of ₹1,200 crore.","Enterprise value equals market capitalisation."),
   ("PEG ratio","The PEG ratio divides the P/E by the expected earnings growth rate, adjusting the multiple for growth.","A P/E of 30 with growth of 15% gives a PEG of 2.","The PEG ratio is the P/E multiplied by growth."),
   ("Relative valuation","Relative valuation values a security by comparing multiples with those of similar companies or its own history.","An analyst compares a bank's P/B with peers.","Relative valuation requires projecting cash flows."),
   ("Sum-of-the-parts","Sum-of-the-parts values each business unit separately and adds them, useful for conglomerates.","An analyst values a group's three divisions separately and sums them.","Sum-of-the-parts uses only a single multiple."),
   ("Sensitivity analysis","Sensitivity analysis shows how the valuation changes when key assumptions such as growth or discount rate are altered.","An analyst shows value at different discount rates.","Sensitivity analysis fixes all assumptions."),
   ("Intrinsic versus market value","A recommendation compares intrinsic value with market price: buy if undervalued, sell if overvalued, after allowing a margin of safety.","An analyst recommends buying when the market price is below fair value.","Market value always equals intrinsic value."),
   ("Equity risk premium","The equity risk premium is the extra return investors require from equities over the risk-free rate.","Investors demand 6% more than government bonds for equity risk.","The equity risk premium equals the risk-free rate."),
   ("Book value","Book value per share is shareholders' equity divided by shares outstanding, from the balance sheet.","Equity of ₹500 crore on 10 crore shares is ₹50 per share.","Book value per share is the market price."),
   ("Cyclically adjusted earnings","For cyclical firms, valuation based on peak or trough earnings misleads, so analysts use average or normalised earnings.","An analyst uses mid-cycle earnings for a steel company.","Peak earnings are always the right base for cyclical stocks.")]),
 dict(n=11, title="Fundamental analysis of commodities", w=5,
  overview="Commodities are valued by supply, demand and cost of carry rather than earnings.",
  focus=["Demand and supply drivers.", "Contango and backwardation.", "Bullion and energy factors."],
  facts=[("Commodity price drivers","Commodity prices are driven by supply, demand, inventories, weather, policy and the currency.","A poor monsoon cuts crop output and raises prices.","Commodity prices depend only on company earnings."),
   ("Stock-to-use ratio","The stock-to-use ratio compares closing stocks with consumption; low levels signal tightness and price pressure.","Inventories fall to a few weeks of consumption and prices rise.","A low stock-to-use ratio signals oversupply."),
   ("Seasonality","Agricultural commodities show seasonal price patterns tied to harvests and demand cycles.","Prices of a crop tend to fall after harvest.","Seasonality is unimportant for agricultural prices."),
   ("Cost of carry in commodities","The cost of carry includes storage, insurance and financing costs, and links futures prices to spot prices.","A commodity future trades above spot by the cost of storing it.","Cost of carry has no effect on futures prices."),
   ("Gold drivers","Gold prices are influenced by real interest rates, the US dollar, central bank buying, inflation expectations and risk sentiment.","Gold rises when real interest rates fall.","Gold falls whenever inflation expectations rise."),
   ("Crude oil drivers","Crude oil prices are driven by OPEC+ decisions, global demand, inventories and geopolitical events.","Production cuts by major producers raise prices.","Crude oil prices are unaffected by supply decisions."),
   ("Currency link","Many commodities are priced in dollars, so a weaker rupee raises their domestic prices, other things equal.","Imported edible oil gets costlier when the rupee falls.","The rupee has no effect on domestic commodity prices."),
   ("Futures curve","The futures curve plots prices across expiries; contango signals plentiful supply and backwardation signals tightness.","Near-month prices exceed far-month prices when supply is short.","Backwardation means plentiful supply.")]),
 dict(n=12, title="Fundamentals of risk and return", w=7,
  overview="The portfolio theory behind research: expected return, volatility, correlation and CAPM.",
  focus=["Risk measures.", "Correlation and diversification.", "CAPM and risk-adjusted performance."],
  visuals=[("formula", "Sharpe ratio", "Sharpe = (Portfolio return − Risk-free return) ÷ Standard deviation")],
  facts=[("Expected return","Expected return is the probability-weighted average of possible returns of an investment.","An asset has a 50% chance of 20% and a 50% chance of 0%, giving 10%.","Expected return is the highest possible return."),
   ("Variance and standard deviation","Variance measures the dispersion of returns around the mean; standard deviation is its square root and the common measure of volatility.","A stock's returns swing widely around its average.","Standard deviation is the average return."),
   ("Correlation","Correlation measures how two assets move together, from −1 to +1; lower correlation gives greater diversification benefit.","Two assets with correlation near zero reduce portfolio volatility when combined.","A correlation of +1 gives the best diversification."),
   ("Systematic risk and beta","Systematic risk is market-wide and measured by beta; it cannot be diversified away.","A stock with beta 1.3 amplifies market moves.","Beta measures company-specific risk."),
   ("CAPM","The Capital Asset Pricing Model states that expected return equals the risk-free rate plus beta times the market risk premium.","A stock's required return is built from risk-free rate and market risk premium.","CAPM says return depends on total risk."),
   ("Security market line","The security market line plots expected return against beta; securities above it are undervalued.","A stock offering more return than CAPM predicts lies above the line.","The security market line plots return against standard deviation."),
   ("Sharpe ratio","The Sharpe ratio is excess return over the risk-free rate divided by standard deviation, measuring return per unit of total risk.","A fund earns 14% with risk-free 6% and standard deviation 16%, giving 0.5.","The Sharpe ratio uses beta as the risk measure."),
   ("Treynor ratio","The Treynor ratio is excess return divided by beta, measuring return per unit of systematic risk.","A portfolio's excess return is divided by its beta.","The Treynor ratio uses standard deviation."),
   ("Jensen's alpha","Jensen's alpha is the return in excess of the CAPM-predicted return, showing a manager's value addition.","A fund earns 2% more than CAPM predicts.","A negative alpha indicates outperformance."),
   ("Efficient frontier","The efficient frontier is the set of portfolios offering the highest expected return for each level of risk.","A set of optimal portfolios that cannot be improved on both return and risk.","Every portfolio lies on the efficient frontier."),
   ("Risk-free rate","The risk-free rate is the return on an investment with no default risk, such as the government security yield.","A ten-year G-sec yield is used as the base rate.","The risk-free rate is the rate on corporate bonds."),
   ("Diversification benefit","Combining imperfectly correlated assets reduces portfolio risk without a proportional fall in return.","Adding gold to an equity portfolio smooths overall volatility.","Diversification increases portfolio risk."),
   ("Downside risk","Downside risk measures the chance and size of losses below a target, as in semi-deviation or maximum drawdown.","An investor tracks how far a fund fell from its peak.","Downside risk counts only positive returns."),
   ("Maximum drawdown","Maximum drawdown is the largest peak-to-trough fall in value over a period, showing the worst loss an investor would have faced.","A fund fell 35% from its high before recovering.","Maximum drawdown is the highest gain.")]),
 dict(n=13, title="Qualities of a good research report", w=5,
  overview="What separates a useful report from a promotional one: structure, clarity, evidence and honesty.",
  focus=["Structure and content of a report.", "Rating and target price.", "Risks and disclosures."],
  facts=[("Report structure","A good report has a clear recommendation, summary, business overview, financial analysis, valuation, risks and disclosures.","A report opens with the rating and the key reasons.","A report need not state a recommendation."),
   ("Recommendation and rating","A rating such as buy, hold or sell must be defined, with the basis stated, and applied consistently.","A report defines buy as an expected return above 15% over twelve months.","Ratings can be undefined labels."),
   ("Target price","A target price is the analyst's estimate of a security's price over a stated horizon, backed by a valuation method and assumptions.","An analyst sets ₹500 with a twelve-month horizon using a P/E method.","A target price needs no supporting valuation."),
   ("Risk disclosure in reports","A report should state the key risks to its thesis, so readers understand what could go wrong.","A report lists regulatory changes and input costs as risks.","Reports should hide risks to appear persuasive."),
   ("Clarity and objectivity","Clear language, supported claims and balanced treatment of positives and negatives make a report credible.","A report cites sources for each figure.","A good report uses exaggerated claims."),
   ("Reasonable basis","Every recommendation must have a reasonable basis supported by research and data, not mere speculation or rumour.","An analyst bases her call on filings and a valuation model.","A recommendation can rest on market rumours."),
   ("Timeliness and updates","Reports should be updated when material events occur and should state the date and data cut-off.","An analyst revises the target after the quarterly results.","A report never needs revision after publishing."),
   ("Data sources and accuracy","Sources should be reliable and cited, and numbers cross-checked for accuracy.","An analyst verifies figures with filings.","Data need not be checked before publishing.")]),
 dict(n=14, title="Legal and regulatory environment", w=10,
  overview="SEBI's Research Analyst Regulations: registration, conduct, disclosures, trading restrictions, records and penalties. Many exact-rule questions.",
  focus=["Registration and qualification.", "Conflicts and disclosures.", "Trading restrictions.", "Records and client agreement."],
  visuals=[("keynums", [("30 days", "Before report"), ("5 days", "After report"), ("5 years", "Record keeping")])],
  facts=[("SEBI (Research Analysts) Regulations, 2014","These regulations require research analysts and research entities to register with SEBI and follow rules on qualification, conduct, disclosure and records.","A person who publishes recommendations for the public must hold SEBI registration.","Research analysts need no registration."),
   ("Registration and qualification","An individual research analyst must hold the prescribed qualification and the NISM research analyst certification and meet other norms.","A candidate cleared the NISM examination and holds the specified degree.","The NISM certificate is optional for registration."),
   ("Research entity","A research entity is a person such as a broker or company that issues research reports and must be registered; it can employ analysts.","A brokerage house publishing reports must be a registered entity.","A research entity is an individual client."),
   ("Disclosure of conflicts","A research analyst must disclose any financial interest, ownership or relationship with the subject company in the report.","A report states that the analyst holds shares of the company.","Analysts need not disclose holdings."),
   ("Trading restriction around reports","A research analyst must not deal in securities for 30 days before and 5 days after publishing a report on them.","An analyst cannot trade a stock for a period around her report.","An analyst may trade the stock in the hour before publication."),
   ("Assured returns prohibited","A research analyst must not provide, or claim to provide, assured or guaranteed returns.","A report says 'This stock will double in a year for sure.'","An analyst may guarantee returns for large clients."),
   ("Record keeping","Research analysts must maintain records of research reports, recommendations and the basis for them for at least five years.","An analyst retains her models and reports on file for five years.","Records must be kept for only six months."),
   ("Compliance officer","Registered research entities must appoint a compliance officer who monitors compliance and reports to SEBI as required.","A firm assigns a person to monitor adherence to regulations.","A compliance officer is optional."),
   ("Chinese wall","A Chinese wall is a set of information barriers that separates research from other business such as investment banking and trading to prevent misuse of sensitive information.","The research desk is kept apart from the banking desk.","A Chinese wall allows free flow of information."),
   ("Front running","Front running is trading ahead of a client's order or an upcoming report to profit from its expected impact, and is prohibited.","An analyst buys shares before releasing a strong buy report.","Front running is allowed if disclosed at a later date."),
   ("Insider information","An analyst must not use or share unpublished price-sensitive information, which is an offence under insider trading rules.","An analyst learns of a merger from a source and trades on it.","Using inside information is permitted for research analysts."),
   ("Client agreement","An analyst providing services to clients must sign an agreement stating the services, fees and terms, and give disclosures.","A client signs a document setting out the services and fees.","A written agreement is unnecessary."),
   ("Public appearance disclosures","When an analyst makes a public appearance, she must disclose any conflicts or holdings in the stocks she discusses.","A television analyst states that she owns the stock she is recommending.","Disclosures are required only in written reports."),
   ("Prohibited compensation","A research analyst must not accept compensation from a subject company that could influence the opinion, and any compensation must be disclosed.","An analyst refuses payment from the company she is covering.","An analyst may accept gifts from the company with no disclosure."),
   ("Grievance and penalties","Violations of the regulations can lead to penalties, suspension or cancellation of registration by SEBI.","A registered analyst whose rules violations are proven faces a regulatory penalty.","SEBI has no power to penalise research analysts."),
   ("Recommendation requirements","Each recommendation must be supported by research data and a rating system, and reports must carry the required disclaimers and disclosures.","A report includes disclosures and the basis of the rating.","Reports need not carry any disclaimers."),
   ("Associate's trading","The trading restrictions and disclosure duties also apply to an analyst's associates and relatives where specified in the regulations.","The analyst's spouse trading ahead of a report breaches the rule.","Restrictions apply to analysts only, never to relatives."),
   ("Rating and price target history","A research entity should keep and show past ratings and price targets, so readers can see the track record.","A report includes a table of previous ratings.","Past ratings are removed from reports.")]),
 dict(n=15, title="Technical analysis", w=15,
  overview="Reading price and volume: trends, patterns, indicators and their limits. The largest single chapter.",
  focus=["Dow theory and trends.", "Support and resistance.", "Moving averages, RSI, MACD, Bollinger.", "Candlesticks and chart patterns.", "Volume and breadth."],
  visuals=[("table", "Common candlestick signals", [["Pattern", "Meaning"], ["Hammer", "Possible bullish reversal after a fall"], ["Shooting star", "Possible bearish reversal after a rise"], ["Bullish engulfing", "Strong buying after a decline"], ["Doji", "Indecision"]], [150, 320])],
  facts=[("Dow theory","Dow theory holds that markets move in primary, secondary and minor trends, and that averages must confirm each other.","An analyst views a multi-year uptrend with corrections inside it.","Dow theory says market trends are unpredictable noise."),
   ("Trend","A trend is the general direction of price movement: an uptrend has higher highs and higher lows, a downtrend lower highs and lower lows.","A chart shows each peak and trough above the last.","An uptrend has lower highs."),
   ("Support","Support is a price level where buying interest is strong enough to stop a decline temporarily.","A stock repeatedly bounces from ₹100.","Support is a level where selling prevents any rise."),
   ("Resistance","Resistance is a price level where selling pressure tends to halt a rise temporarily.","A stock fails to cross ₹150 several times.","Resistance is a level where buyers appear."),
   ("Breakout","A breakout is a price move beyond support or resistance, ideally on higher volume, signalling a possible new trend.","A stock closes above its long-held resistance on heavy volume.","A breakout on very low volume is the most reliable."),
   ("Simple moving average","A simple moving average is the average closing price over a set number of periods, smoothing price data to show the trend.","A 50-day average of closing prices.","A moving average shows a single day's high."),
   ("Exponential moving average","An exponential moving average gives greater weight to recent prices and reacts faster than a simple average.","An analyst prefers an average that responds more quickly to new prices.","An EMA gives equal weight to all days."),
   ("Golden cross","A golden cross occurs when a shorter-term average, such as the 50-day, crosses above a longer-term average, such as the 200-day, a bullish signal.","The 50-day average rises above the 200-day average.","A golden cross is a bearish signal."),
   ("Death cross","A death cross occurs when the 50-day average crosses below the 200-day average, a bearish signal.","The shorter average falls beneath the longer one.","A death cross is a bullish signal."),
   ("RSI","The Relative Strength Index is a momentum oscillator from 0 to 100; above 70 is considered overbought and below 30 oversold.","A reading of 78 suggests the stock may be overbought.","An RSI above 70 means oversold."),
   ("MACD","MACD is the difference between a 12-period and 26-period EMA, with a 9-period signal line; crossovers indicate momentum changes.","A line crossing above its signal line suggests rising momentum.","MACD measures trading volume."),
   ("Bollinger Bands","Bollinger Bands plot a moving average with bands two standard deviations above and below, showing volatility and extremes.","Bands widen when volatility rises.","Bollinger Bands show company earnings."),
   ("Stochastic oscillator","The stochastic oscillator compares a closing price with the range over a period; above 80 is overbought and below 20 oversold.","A reading of 15 suggests an oversold stock.","A stochastic reading above 80 is oversold."),
   ("On-balance volume","On-balance volume adds volume on up days and subtracts it on down days, to see whether volume confirms the price trend.","A rising price with falling OBV is a warning sign.","OBV is a measure of earnings."),
   ("Volume confirmation","A price move accompanied by rising volume is considered more reliable than one on thin volume.","A rally on heavy volume is trusted more.","Volume is irrelevant to price moves."),
   ("Head and shoulders","A head and shoulders pattern has three peaks, with the middle highest, and signals a potential trend reversal from up to down when the neckline breaks.","A chart shows a left shoulder, higher head and right shoulder.","A head and shoulders pattern signals a continuing uptrend."),
   ("Double top","A double top is a bearish reversal pattern in which price makes two peaks at a similar level and then breaks below the trough between them.","Price hits ₹200 twice and falls.","A double top is a bullish pattern."),
   ("Double bottom","A double bottom is a bullish reversal pattern with two troughs at a similar level followed by a break above the middle peak.","Price falls to ₹80 twice and then rises.","A double bottom is a bearish pattern."),
   ("Triangle pattern","Triangles are consolidation patterns where price ranges narrow; ascending triangles often break upward and descending ones downward.","Price makes lower highs and a flat support line.","Triangles show the maximum volatility."),
   ("Cup and handle","The cup and handle is a bullish continuation pattern with a rounded bottom followed by a small pullback before a breakout.","A rounded base is followed by a small consolidation and a rise.","A cup and handle is a bearish reversal."),
   ("Candlestick","A candlestick shows open, high, low and close for a period, with the body showing the open-to-close range and wicks showing extremes.","A candle has a long lower wick and small body.","A candlestick shows only closing price."),
   ("Doji","A doji forms when the open and close are almost equal, signalling indecision between buyers and sellers.","A candle with almost no body and long wicks.","A doji shows a strong trend."),
   ("Bullish engulfing","A bullish engulfing pattern is a large up candle that completely covers the previous down candle, suggesting a reversal upwards.","A big green candle swallows the previous red one after a decline.","A bullish engulfing pattern appears at the top of an uptrend."),
   ("Fibonacci retracement","Fibonacci retracement levels such as 38.2%, 50% and 61.8% mark likely pullback areas within a trend.","A stock falls back to 61.8% of the previous rally and bounces.","Fibonacci levels predict company earnings."),
   ("Gap","A gap is an empty space between one day's range and the next, showing sudden change in sentiment, often after news.","A stock opens well above the previous day's high.","A gap means the stock did not trade."),
   ("Advance-decline line","The advance-decline line tracks the number of advancing minus declining stocks and shows the breadth of a market move.","The index rises while fewer stocks advance, a sign of narrow breadth.","The advance-decline line measures interest rates."),
   ("Open interest in analysis","Rising open interest with rising prices indicates fresh buying and strengthens the trend; falling open interest suggests short covering or unwinding.","Prices and open interest rise together.","Open interest measures a stock's daily volume."),
   ("Limitations of technical analysis","Technical signals can fail and give false breakouts; they are best used with risk limits and alongside other analysis.","A breakout reverses within days and stops out traders.","Technical signals are always accurate."),
   ("Elliott wave","Elliott wave theory proposes that markets move in repeating waves of five impulse and three corrective moves, although interpretation is subjective.","An analyst labels price moves as waves.","Elliott wave is a precise mathematical law."),
   ("Relative strength comparison","Relative strength compares a security's performance with a benchmark or peers to identify leaders and laggards.","An analyst picks stocks outperforming the index.","Relative strength is the same as RSI.")]),
])
